      "findings": [
        {
          "source_quote": "ἅτε δὴ καὶ τοῖς σώμασιν ὑπερέχουσαι",
          "english_quote": "just as they also exceeded them in bodily size",
          "issue": "ἅτε δή introduces the factual ground for the preceding statement, not merely a parallel comparison. 'Just as' weakens the author's explanation that the greater bodily size grounds the greater size of the souls. The note discusses the comparison and its metonymic subject but overlooks this causal connection.",
          "suggested_revision": "Replace this phrase with 'since they also surpassed them in bodily size' and amend the note to explain the causal force of ἅτε δή while retaining the disclosure about the bodily comparison's grammatical subject.",
          "severity": "major"
        }
      ]
